using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Security.Cryptography;using System.Text;using Microsoft.AspNetCore.WebUtilities;using Microsoft.Extensions.Configuration;using Microsoft.IdentityModel.Tokens;using NexHire.Application.Interfaces.Services;using NexHire.Domain.Entities;
namespace NexHire.Infrastructure.Authentication;
public sealed class JwtTokenGenerator(IConfiguration config):ITokenService
{
    public(string Token,DateTime ExpiresAtUtc)CreateAccessToken(User user){var key=config["Jwt:Key"]??throw new InvalidOperationException("Jwt:Key missing.");if(Encoding.UTF8.GetByteCount(key)<32)throw new InvalidOperationException("JWT key must contain at least 32 bytes.");var expires=DateTime.UtcNow.AddMinutes(config.GetValue<int?>("Jwt:ExpiryMinutes")??60);var claims=new[]{new Claim(JwtRegisteredClaimNames.Sub,user.Id.ToString()),new Claim(ClaimTypes.NameIdentifier,user.Id.ToString()),new Claim(JwtRegisteredClaimNames.Email,user.Email),new Claim(ClaimTypes.Name,user.FullName),new Claim(ClaimTypes.Role,user.Role.ToString()),new Claim(JwtRegisteredClaimNames.Jti,Guid.NewGuid().ToString())};var jwt=new JwtSecurityToken(config["Jwt:Issuer"],config["Jwt:Audience"],claims,expires:expires,signingCredentials:new(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),SecurityAlgorithms.HmacSha256));return(new JwtSecurityTokenHandler().WriteToken(jwt),expires);}
    public string CreateSecureToken()=>WebEncoders.Base64UrlEncode(RandomNumberGenerator.GetBytes(64));public string HashToken(string value)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
}
